use crate::adapter::{ActionOps, InputOps, ObservationOps, SystemOps};
use crate::launch_options::LaunchOptions;
use crate::{AdapterError, AppError, AppInfo, InteractionLease, ProcessId, RendererKind};
use std::io::{Read, Write};
use std::net::TcpListener;
use std::sync::Mutex;
use std::sync::atomic::{AtomicUsize, Ordering};

/// Mock adapter for the `--cdp` wiring: records the options `launch_app`
/// actually received, and can optionally serve a canned `/json/version`
/// response on the requested port so the endpoint-verified path is testable
/// without a real Chromium-based application. Shared by every `--cdp` test
/// module in this file's family so the mock is defined once.
pub(super) struct CdpAdapter {
    pub(super) running: Vec<AppInfo>,
    pub(super) list_apps_calls: AtomicUsize,
    pub(super) launch_app_calls: AtomicUsize,
    pub(super) serve_cdp: bool,
    pub(super) renderer: Option<RendererKind>,
    pub(super) captured_args: Mutex<Vec<String>>,
    pub(super) captured_cdp_port: Mutex<Option<u16>>,
}

impl ObservationOps for CdpAdapter {
    fn list_apps(&self, _deadline: crate::Deadline) -> Result<Vec<AppInfo>, AdapterError> {
        self.list_apps_calls.fetch_add(1, Ordering::SeqCst);
        Ok(self.running.clone())
    }
}
impl ActionOps for CdpAdapter {}
impl InputOps for CdpAdapter {}

impl SystemOps for CdpAdapter {
    fn acquire_interaction_lease(
        &self,
        deadline: crate::Deadline,
    ) -> Result<InteractionLease, AdapterError> {
        InteractionLease::guarded(deadline, ())
    }

    fn launch_app(
        &self,
        _id: &str,
        options: &LaunchOptions,
        _lease: &InteractionLease,
    ) -> Result<crate::launch_result::LaunchResult, AdapterError> {
        self.launch_app_calls.fetch_add(1, Ordering::SeqCst);
        *self.captured_args.lock().unwrap() = options.args.clone();
        *self.captured_cdp_port.lock().unwrap() = options.cdp_port;
        if self.serve_cdp {
            let port = options.cdp_port.expect("cdp_port resolved before launch");
            serve_fake_cdp_endpoint(port);
        }
        Ok(crate::launch_result::LaunchResult {
            app: "Fixture".into(),
            pid: ProcessId::new(42),
            process_instance: Some("42:1".into()),
            window: None,
            cdp: None,
            renderer: self.renderer,
            suggestion: None,
        })
    }
}

fn serve_fake_cdp_endpoint(port: u16) {
    let listener = TcpListener::bind(("127.0.0.1", port)).expect("port was reserved by the caller");
    std::thread::spawn(move || {
        if let Ok((mut stream, _)) = listener.accept() {
            let mut buf = [0_u8; 1024];
            let _ = stream.read(&mut buf);
            let body = r#"{"Browser":"Fixture/1.0","webSocketDebuggerUrl":"ws://127.0.0.1/devtools/browser/fixture"}"#;
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\n\r\n{}",
                body.len(),
                body
            );
            let _ = stream.write_all(response.as_bytes());
        }
    });
}

pub(super) fn empty_cdp_adapter(serve_cdp: bool) -> CdpAdapter {
    CdpAdapter {
        running: Vec::new(),
        list_apps_calls: AtomicUsize::new(0),
        launch_app_calls: AtomicUsize::new(0),
        serve_cdp,
        renderer: None,
        captured_args: Mutex::new(Vec::new()),
        captured_cdp_port: Mutex::new(None),
    }
}

pub(super) fn adapter_error(error: AppError) -> AdapterError {
    match error {
        AppError::Adapter(inner) => inner,
        other => panic!("expected an adapter error, got {other:?}"),
    }
}

use crate::{AdapterError, ErrorCode, adapter::NativeHandle};
use std::sync::atomic::{AtomicU32, Ordering};

pub(crate) struct StaleRetryCounter {
    calls: AtomicU32,
    fail_until: u32,
}

impl StaleRetryCounter {
    pub(crate) fn new(fail_until: u32) -> Self {
        Self {
            calls: AtomicU32::new(0),
            fail_until,
        }
    }

    pub(crate) fn attempt(&self) -> Result<NativeHandle, AdapterError> {
        let n = self.calls.fetch_add(1, Ordering::SeqCst) + 1;
        if n <= self.fail_until {
            return Err(AdapterError::new(ErrorCode::StaleRef, "not yet resolvable")
                .with_details(serde_json::json!({ "retryable": true })));
        }
        Ok(NativeHandle::null())
    }

    pub(crate) fn calls(&self) -> u32 {
        self.calls.load(Ordering::SeqCst)
    }
}

/// What `find_named_descendant` is looking for. An open-menu search takes the
/// first matching item, while a collection search must see every candidate to
/// prove the match is unique — so only a collection search still reads children
/// at the depth cap, where they decide whether the search can fail closed.
#[derive(Clone, Copy)]
pub(crate) enum SelectSearch {
    MenuItem,
    Collection,
}

#!/usr/bin/env python3
import fcntl
import os
import stat
import subprocess
import sys


LEASE_FD_ENV = "AGENT_DESKTOP_INTERACTION_LEASE_FD"


def canonical_lock_path(root="/tmp"):
    directory = os.path.join(root, f"agent-desktop-{os.geteuid()}")
    return directory, os.path.join(directory, "interaction.lock")


def _prepare_directory(directory):
    try:
        os.mkdir(directory, 0o700)
    except FileExistsError:
        pass
    metadata = os.lstat(directory)
    if not stat.S_ISDIR(metadata.st_mode) or stat.S_ISLNK(metadata.st_mode):
        raise RuntimeError("interaction lease parent is not a real directory")
    if metadata.st_uid != os.geteuid():
        raise RuntimeError("interaction lease parent is not owned by this user")
    os.chmod(directory, 0o700)


def acquire(root="/tmp"):
    directory, path = canonical_lock_path(root)
    _prepare_directory(directory)
    flags = os.O_RDWR | os.O_CREAT
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    fd = os.open(path, flags, 0o600)
    metadata = os.fstat(fd)
    if not stat.S_ISREG(metadata.st_mode) or metadata.st_uid != os.geteuid():
        os.close(fd)
        raise RuntimeError("interaction lease is not a private user-owned regular file")
    if metadata.st_nlink != 1:
        os.close(fd)
        raise RuntimeError("interaction lease has an unexpected link count")
    os.fchmod(fd, 0o600)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        os.close(fd)
        return None
    os.set_inheritable(fd, True)
    return fd


def verify_inherited(raw_fd):
    fd = int(raw_fd)
    if fd < 0:
        raise ValueError("interaction lease FD must be nonnegative")
    metadata = os.fstat(fd)
    _, path = canonical_lock_path()
    canonical = os.stat(path, follow_symlinks=False)
    if (metadata.st_dev, metadata.st_ino) != (canonical.st_dev, canonical.st_ino):
        raise RuntimeError("interaction lease FD does not identify the canonical lock")
    return fd


def run(command):
    fd = acquire()
    if fd is None:
        print("SKIP (blocked): canonical desktop interaction lease is held", file=sys.stderr)
        return 2
    try:
        environment = os.environ.copy()
        environment[LEASE_FD_ENV] = str(fd)
        return subprocess.run(command, env=environment, pass_fds=(fd,), check=False).returncode
    finally:
        os.close(fd)


def main():
    if len(sys.argv) >= 3 and sys.argv[1] == "run":
        raise SystemExit(run(sys.argv[2:]))
    if len(sys.argv) == 3 and sys.argv[1] == "verify":
        verify_inherited(sys.argv[2])
        return
    raise SystemExit("usage: interaction_lock.py run COMMAND... | verify FD")


if __name__ == "__main__":
    main()

const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const {
  chmodSync,
  existsSync,
  mkdtempSync,
  mkdirSync,
  readFileSync,
  writeFileSync,
} = require('node:fs');
const { tmpdir } = require('node:os');
const { join } = require('node:path');
const { afterEach, test } = require('node:test');

const postinstall = require('../../npm/scripts/postinstall.js');

const roots = [];

afterEach(() => {
  delete process.env.AGENT_DESKTOP_MACOS_HELPER_PATH;
  for (const root of roots.splice(0)) {
    postinstall.trashRecoverably(root);
  }
});

function temporaryDirectory() {
  const root = mkdtempSync(join(tmpdir(), 'agent-desktop-npm-test-'));
  roots.push(root);
  return root;
}

function archive(entries) {
  const root = temporaryDirectory();
  const source = join(root, 'source');
  mkdirSync(source);
  for (const [name, contents] of Object.entries(entries)) {
    const path = join(source, name);
    writeFileSync(path, contents, { mode: 0o755 });
    chmodSync(path, 0o755);
  }
  const tarball = join(root, 'release.tar.gz');
  execFileSync('tar', ['-czf', tarball, '-C', source, ...Object.keys(entries)]);
  return { root, tarball };
}

function executable(contents) {
  const root = temporaryDirectory();
  const path = join(root, 'trash');
  writeFileSync(path, contents, { mode: 0o755 });
  return path;
}

function captureWarnings(run) {
  const warnings = [];
  const write = process.stderr.write;
  process.stderr.write = (chunk) => {
    warnings.push(String(chunk));
    return true;
  };
  try {
    run();
    return warnings.join('');
  } finally {
    process.stderr.write = write;
  }
}

test('checksum lookup requires an exact archive name', () => {
  const hash = 'a'.repeat(64);
  assert.equal(postinstall.checksumFor(`${hash}  release.tar.gz\n`, 'release.tar.gz'), hash);
  assert.throws(
    () => postinstall.checksumFor(`${hash}  old-release.tar.gz\n`, 'release.tar.gz'),
    /Checksum entry missing/,
  );
});

test('archive validation rejects missing and additional payloads', () => {
  const valid = archive({
    'agent-desktop': 'cli',
    'agent-desktop-macos-helper': 'helper',
  });
  postinstall.validateArchive(valid.tarball);

  const extra = archive({
    'agent-desktop': 'cli',
    'agent-desktop-macos-helper': 'helper',
    'unexpected': 'payload',
  });
  assert.throws(() => postinstall.validateArchive(extra.tarball), /unexpected entries/);
});

test('archive installation preserves the exact paired executables', () => {
  const payload = archive({
    'agent-desktop': 'cli-build-v1',
    'agent-desktop-macos-helper': 'helper-build-v1',
  });
  const destination = temporaryDirectory();
  const binary = join(destination, 'agent-desktop-darwin-arm64');
  const helper = join(destination, 'agent-desktop-macos-helper');

  postinstall.installArchive(payload.tarball, binary, helper);

  assert.equal(readFileSync(binary, 'utf8'), 'cli-build-v1');
  assert.equal(readFileSync(helper, 'utf8'), 'helper-build-v1');
});

test('recoverable cleanup invokes trash and removes the original path', () => {
  const target = temporaryDirectory();
  const recovered = `${target}.recovered`;
  roots.push(recovered);
  const fakeTrash = executable('#!/bin/sh\nmv "$1" "$1.recovered"\n');

  postinstall.trashRecoverably(target, fakeTrash);
  assert.equal(existsSync(target), false);
  assert.equal(existsSync(recovered), true);
});

test('recoverable cleanup retains artifacts and warns when trash is unavailable or fails', () => {
  const unavailable = temporaryDirectory();
  const failing = temporaryDirectory();
  const fakeTrash = executable('#!/bin/sh\nexit 9\n');

  for (const [target, command, reason] of [
    [
      unavailable,
      '/definitely-missing-agent-desktop-trash',
      'trash command is unavailable: /definitely-missing-agent-desktop-trash',
    ],
    [failing, fakeTrash, 'trash exited with status 9'],
  ]) {
    const warnings = captureWarnings(() =>
      postinstall.trashRecoverably(target, command),
    );
    assert.equal(existsSync(target), true);
    assert.ok(warnings.includes(`retained at ${target}:`));
    assert.ok(warnings.includes(reason));
  }
});

test('cleanup failure does not mask a successful archive install', () => {
  const payload = archive({
    'agent-desktop': 'cli-build-v2',
    'agent-desktop-macos-helper': 'helper-build-v2',
  });
  const destination = temporaryDirectory();
  const binary = join(destination, 'agent-desktop-darwin-arm64');
  const helper = join(destination, 'agent-desktop-macos-helper');

  const warnings = captureWarnings(() =>
    postinstall.installArchive(
      payload.tarball,
      binary,
      helper,
      '/definitely-missing-agent-desktop-trash',
    ),
  );

  assert.equal(readFileSync(binary, 'utf8'), 'cli-build-v2');
  assert.equal(readFileSync(helper, 'utf8'), 'helper-build-v2');
  assert.match(warnings, /Could not move cleanup artifact to Trash; retained at .*\.extract-/);
  const retained = warnings.match(/retained at (.*\.extract-[^:]+):/)?.[1];
  assert.ok(retained);
  assert.equal(existsSync(retained), true);
  roots.push(retained);
});

test('custom helper override must be absolute', () => {
  process.env.AGENT_DESKTOP_MACOS_HELPER_PATH = 'relative-helper';
  assert.throws(
    () => postinstall.customHelperPath('/tmp/agent-desktop'),
    /must be an absolute path/,
  );
});

use agent_desktop_core::{
    PlatformAdapter, RefEntry, RefMap, RefStore,
    commands::{click, helpers::RefArgs, wait},
    context::CommandContext,
};
use std::sync::{Mutex, MutexGuard};

static HOME_LOCK: Mutex<()> = Mutex::new(());

pub fn run_click_command(
    adapter: &dyn PlatformAdapter,
    entry: RefEntry,
) -> Result<serde_json::Value, agent_desktop_core::AppError> {
    let context = CommandContext::default();
    with_saved_entry(entry, &context, |snapshot_id| {
        click::execute(
            RefArgs {
                ref_id: "@e1".into(),
                snapshot_id: Some(snapshot_id),
                timeout_ms: None,
            },
            adapter,
            &context,
        )
    })
}

pub fn run_wait_element_command(
    adapter: &dyn PlatformAdapter,
    entry: RefEntry,
    context: &CommandContext,
) -> Result<serde_json::Value, agent_desktop_core::AppError> {
    run_wait_element_command_with_predicate(adapter, entry, context, WaitPredicate::new("exists"))
}

pub fn run_wait_element_command_with_predicate(
    adapter: &dyn PlatformAdapter,
    entry: RefEntry,
    context: &CommandContext,
    predicate: WaitPredicate<'_>,
) -> Result<serde_json::Value, agent_desktop_core::AppError> {
    with_saved_entry(entry, context, |snapshot_id| {
        wait::execute(
            wait::WaitArgs {
                mode: wait::WaitModeArgs {
                    ms: None,
                    element: Some("@e1".into()),
                    window: None,
                    text: None,
                    surface: None,
                    event: None,
                    window_id: None,
                },
                predicate: wait::WaitPredicateArgs {
                    snapshot_id: Some(snapshot_id),
                    predicate: Some(predicate.name.into()),
                    value: predicate.value.map(String::from),
                    action: predicate.action.map(String::from),
                    count: None,
                },
                timeout_ms: 250,
                app: None,
            },
            adapter,
            context,
        )
    })
}

pub struct WaitPredicate<'a> {
    name: &'a str,
    value: Option<&'a str>,
    action: Option<&'a str>,
}

impl<'a> WaitPredicate<'a> {
    pub fn new(name: &'a str) -> Self {
        Self {
            name,
            value: None,
            action: None,
        }
    }

    pub fn with_value(mut self, value: &'a str) -> Self {
        self.value = Some(value);
        self
    }

    pub fn with_action(mut self, action: &'a str) -> Self {
        self.action = Some(action);
        self
    }
}

fn with_saved_entry<T>(
    entry: RefEntry,
    context: &CommandContext,
    run: impl FnOnce(String) -> Result<T, agent_desktop_core::AppError>,
) -> Result<T, agent_desktop_core::AppError> {
    let _home = TestHome::new();
    let mut refmap = RefMap::new();
    refmap.try_allocate(entry)?;
    let snapshot_id = RefStore::for_session(context.session_id())?.save_new_snapshot(&refmap)?;
    run(snapshot_id)
}

struct TestHome {
    _lock: MutexGuard<'static, ()>,
    dir: std::path::PathBuf,
    prev: Option<std::ffi::OsString>,
}

impl TestHome {
    fn new() -> Self {
        let lock = HOME_LOCK.lock().unwrap();
        let dir = temp_path("home");
        std::fs::create_dir_all(&dir).unwrap();
        let prev = std::env::var_os("HOME");
        unsafe { std::env::set_var("HOME", &dir) };
        Self {
            _lock: lock,
            dir,
            prev,
        }
    }
}

impl Drop for TestHome {
    fn drop(&mut self) {
        match self.prev.as_ref() {
            Some(prev) => unsafe { std::env::set_var("HOME", prev) },
            None => unsafe { std::env::remove_var("HOME") },
        }
        let _ = std::fs::remove_dir_all(&self.dir);
    }
}

fn temp_path(label: &str) -> std::path::PathBuf {
    std::env::temp_dir().join(format!(
        "agent-desktop-conformance-{label}-{}",
        unique_suffix()
    ))
}

fn unique_suffix() -> u128 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos()
}

